from django import forms

class RegistroForm(forms.Form):
    email = forms.EmailField()
    clave = forms.CharField(widget=forms.PasswordInput)
    confirmar_clave = forms.CharField(widget=forms.PasswordInput)

    def clean_email(self):
        email = self.cleaned_data.get("email")
        if not email.endswith("@koda.academy"):
            raise forms.ValidationError("El correo debe pertenecer al dominio @koda.academy")
        return email.lower()

    def clean(self):
        cleaned_data = super().clean()
        clave = cleaned_data.get("clave")
        confirmacion = cleaned_data.get("confirmar_clave")
        if clave and confirmacion and clave != confirmacion:
            raise forms.ValidationError("Las contraseñas no coinciden")
        return cleaned_data

