from django import forms

class PerfilForm(forms.Form):
    edad = forms.IntegerField()

    def clean_edad(self):
        edad = self.cleaned_data.get("edad")
        if edad is not None and edad < 18:
            raise forms.ValidationError("Debes ser mayor de edad")
        return edad

